package com.morongaming.forsakenrealm;
import android.content.Context;
import android.graphics.*;
import android.view.*;
import org.json.*;
import java.util.*;
final class LootView extends View {
 interface Host{JSONObject container();JSONObject player();void transfer(String item,boolean deposit);void close();String status();}
 final Host host;final Paint p=new Paint(3);final Map<String,String> names=new HashMap<>();final Map<String,Integer> rarities=new HashMap<>();int leftPage,rightPage,dragSide=-1;String dragItem;float dragX,dragY,downX,downY;
 LootView(Context context,Host h){super(context);host=h;try(java.io.InputStream in=context.getAssets().open("progression-data.json")){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);JSONArray items=new JSONObject(out.toString("UTF-8")).getJSONArray("items");for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);names.put(item.getString("id"),item.getString("name"));rarities.put(item.getString("id"),Rarity.level(item));}}catch(Exception ignored){}}
 ArrayList<String> keys(JSONObject items){ArrayList<String> a=new ArrayList<>();if(items!=null){Iterator<String> it=items.keys();while(it.hasNext()){String k=it.next();if(items.optInt(k)>0)a.add(k);}}Collections.sort(a);return a;}
 JSONObject items(int side){JSONObject c=host.container();return side==0?(c==null?null:c.optJSONObject("items")):host.player().optJSONObject("inventory");}
 void text(Canvas c,String t,float x,float y,float size,int color){p.setTextSize(size);p.setColor(color);c.drawText(t,x,y,p);}
 void box(Canvas c,float x,float y,float w,float h,int color){p.setColor(color);c.drawRoundRect(x,y,x+w,y+h,8,8,p);}
 protected void onDraw(Canvas c){float sx=getWidth()/960f,sy=getHeight()/540f;c.save();c.scale(sx,sy);c.drawColor(0xff17211d);JSONObject container=host.container();String title=container==null?"CONTAINER UNAVAILABLE":container.optString("name");text(c,title.length()>65?title.substring(0,65):title,25,35,22,0xffe1c995);text(c,"CLOSE",855,35,20,Color.WHITE);text(c,"Tap an item or drag it to the opposite panel",25,65,16,0xffbac6b7);
 for(int side=0;side<2;side++){float x=25+side*475;boolean deposit=container!=null&&container.optBoolean("canDeposit");text(c,side==0?"CONTENTS":"BACKPACK"+(deposit?" • Store items":""),x,100,18,0xffd7c9a7);ArrayList<String> keys=keys(items(side));int pages=Math.max(1,(keys.size()+5)/6),page=Math.min(side==0?leftPage:rightPage,pages-1);if(side==0)leftPage=page;else rightPage=page;for(int cell=0;cell<6;cell++){int index=page*6+cell;float bx=x+(cell%2)*220,by=115+(cell/2)*100;box(c,bx,by,210,90,0xff2d3b32);if(index<keys.size()){String key=keys.get(index),name=names.containsKey(key)?names.get(key):key;p.setTextSize(17);while(p.measureText(name)>190&&p.getTextSize()>10)p.setTextSize(p.getTextSize()-1);int rarity=rarities.containsKey(key)?rarities.get(key):1;p.setColor(Rarity.color(rarity));c.drawText(name,bx+10,by+32,p);text(c,"× "+items(side).optInt(key)+" • R"+rarity+" "+Rarity.name(rarity),bx+10,by+66,15,Rarity.color(rarity));}}text(c,"◀ PREV",x,440,17,Color.WHITE);text(c,(page+1)+" / "+pages,x+180,440,17,0xffc5b583);text(c,"NEXT ▶",x+335,440,17,Color.WHITE);}
 box(c,25,462,200,48,0xff74603b);text(c,"TAKE ALL",65,492,19,Color.WHITE);String status=host.status();text(c,status.length()>78?status.substring(0,78):status,245,492,15,0xffd1c6a8);if(dragItem!=null){box(c,dragX-70,dragY-25,140,45,0xee8b7146);text(c,names.containsKey(dragItem)?names.get(dragItem):dragItem,dragX-60,dragY+4,14,Color.WHITE);}c.restore();}
 public boolean onTouchEvent(MotionEvent e){float x=e.getX()*960/getWidth(),y=e.getY()*540/getHeight();if(e.getActionMasked()==MotionEvent.ACTION_DOWN){if(y<65&&x>820){host.close();return true;}if(y>455&&x<230){host.transfer("all",false);return true;}int side=x<480?0:1;float local=x-25-side*475;if(y>410&&y<455){int pages=Math.max(1,(keys(items(side)).size()+5)/6);int page=side==0?leftPage:rightPage;if(local<120)page=Math.max(0,page-1);else if(local>320)page=Math.min(pages-1,page+1);if(side==0)leftPage=page;else rightPage=page;invalidate();return true;}if(y>=115&&y<405&&local>=0&&local<430){int col=(int)(local/220),row=(int)((y-115)/100),idx=(side==0?leftPage:rightPage)*6+row*2+col;ArrayList<String> keys=keys(items(side));if(idx<keys.size()){dragSide=side;dragItem=keys.get(idx);dragX=downX=x;dragY=downY=y;}}}else if(e.getActionMasked()==MotionEvent.ACTION_MOVE){dragX=x;dragY=y;invalidate();}else if(e.getActionMasked()==MotionEvent.ACTION_UP){if(dragItem!=null&&((x<480?0:1)!=dragSide||Math.hypot(x-downX,y-downY)<15))host.transfer(dragItem,dragSide==1);dragItem=null;invalidate();}else if(e.getActionMasked()==MotionEvent.ACTION_CANCEL){dragItem=null;invalidate();}return true;}
}

